// Port browser-side dari Code.gs. Seluruh soal, tabel nilai, kondisi pola,
// dan definisi DISC di atas dipertahankan langsung dari sumber.
export function computeDisc(answers) {
  if (!Array.isArray(answers) || answers.length !== 24) {
    throw new Error('Tes DISC harus memiliki 24 jawaban.');
  }
  const posP = [];
  const posK = [];
  answers.forEach((answer, i) => {
    const most = Number(answer?.most);
    const least = Number(answer?.least);
    if (!Number.isInteger(most) || !Number.isInteger(least) || most < 0 || most > 3 || least < 0 || least > 3 || most === least) {
      throw new Error(`Jawaban soal ${i + 1} tidak valid.`);
    }
    posP.push(most + 1);
    posK.push(least + 1);
  });

  const LETTERS = ['D', 'I', 'S', 'C'];
  const cntP = { D: 0, I: 0, S: 0, C: 0 };
  const cntK = { D: 0, I: 0, S: 0, C: 0 };
  for (let q = 0; q < 24; q++) {
    const lp = SCORE_P[q][posP[q] - 1];
    const lk = SCORE_K[q][posK[q] - 1];
    if (lp !== '*') cntP[lp]++;
    if (lk !== '*') cntK[lk]++;
  }
  const countP = LETTERS.map(L => cntP[L]);
  const countK = LETTERS.map(L => cntK[L]);
  const starP = 24 - countP.reduce((a, b) => a + b, 0);
  const starK = 24 - countK.reduce((a, b) => a + b, 0);
  const diff = countP.map((v, i) => v - countK[i]);

  function lookup(table, keys, x, col) {
    let value = table[0][col];
    for (let k = 0; k < keys.length; k++) {
      if (keys[k] <= x) value = table[k][col];
      else break;
    }
    return value;
  }
  const keysN = Array.from({ length: 21 }, (_, n) => n);
  const keysChange = Array.from({ length: 45 }, (_, i) => i - 22);
  const g1 = countP.map((v, i) => lookup(TABLE_MOST, keysN, v, i));
  const g2 = countK.map((v, i) => lookup(TABLE_LEAST, keysN, v, i));
  const g3 = diff.map((v, i) => lookup(TABLE_CHANGE, keysChange, v, i));

  function matchPattern(values) {
    for (let p = 0; p < PATTERN_CONDITIONS.length; p++) {
      if (PATTERN_CONDITIONS[p](values[0], values[1], values[2], values[3])) return p;
    }
    return -1;
  }
  const indexes = [matchPattern(g1), matchPattern(g2), matchPattern(g3)];
  const pola = indexes.map(i => {
    if (i === -1) return { index: -1, nama: 'Tidak terdefinisi', title: '-', traits: [], professions: '-', description: '-' };
    const d = DEF_DATA[i];
    return { index: i + 1, nama: PATTERN_NAMES[i], title: d.title, traits: d.traits, professions: d.professions, description: d.description };
  });
  let domIdx = 0;
  for (let t = 1; t < 4; t++) if (g3[t] > g3[domIdx]) domIdx = t;
  const hurufDominan = LETTERS[domIdx];
  return { countP, countK, starP, starK, diff, g1, g2, g3, pola, hurufDominan, detail: DETAIL[hurufDominan] };
}

export function ageFromDate(dateValue) {
  if (!dateValue) return '';
  const birth = new Date(`${dateValue}T00:00:00`);
  if (Number.isNaN(birth.getTime())) return '';
  const today = new Date();
  let age = today.getFullYear() - birth.getFullYear();
  const monthDelta = today.getMonth() - birth.getMonth();
  if (monthDelta < 0 || (monthDelta === 0 && today.getDate() < birth.getDate())) age--;
  return age >= 0 && age < 120 ? age : '';
}

export { QUESTIONS, SCORE_P, SCORE_K, TABLE_MOST, TABLE_LEAST, TABLE_CHANGE, PATTERN_NAMES, PATTERN_CONDITIONS, DEF_DATA, DETAIL };
